import re
import shutil
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]


class EnterpriseMetadataTests(unittest.TestCase):
    def test_apm_manifest_is_generated_and_current(self):
        manifest = (ROOT / "apm.yml").read_text(encoding="utf-8")
        self.assertTrue(
            manifest.startswith(
                "# Generated by build/gen_apm_manifests.py -- do not edit by hand.\n"
            )
        )
        self.assertIn("name: fabric-plan-skill\n", manifest)
        self.assertIn("version: 1.0.0\n", manifest)
        self.assertIn("author: Lumel Technologies Inc.\n", manifest)
        result = subprocess.run(
            [sys.executable, "build/gen_apm_manifests.py", "--check"],
            cwd=ROOT,
            text=True,
            capture_output=True,
        )
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_apm_check_rejects_crlf_manifest_drift(self):
        with tempfile.TemporaryDirectory() as folder:
            root = Path(folder)
            (root / "build").mkdir()
            shutil.copy2(ROOT / "build/gen_apm_manifests.py", root / "build/gen_apm_manifests.py")
            shutil.copy2(ROOT / "SKILL.md", root / "SKILL.md")
            manifest = (ROOT / "apm.yml").read_text(encoding="utf-8")
            (root / "apm.yml").write_bytes(manifest.replace("\n", "\r\n").encode("utf-8"))
            result = subprocess.run(
                [sys.executable, "build/gen_apm_manifests.py", "--check"],
                cwd=root,
                text=True,
                capture_output=True,
            )
            self.assertNotEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_skill_ownership_uses_planning_team(self):
        ownership = (ROOT / ".github/skill-ownership.yml").read_text(encoding="utf-8")
        self.assertEqual(
            ownership,
            "schemaVersion: 3\n"
            "teams:\n"
            "  planning:\n"
            "    displayName: Microsoft Fabric Planning\n"
            "    scope: Fabric Plan definition authoring, validation and repair, definition inspection and read-only narratives. Plan item create/rename/delete belong to the plan-cli skill and are not claimed here.\n"
            "skills:\n"
            "  fabric-plan-skill:\n"
            "    owningTeam: planning\n"
            "    area: item\n",
        )

    def test_public_changeset_describes_user_visible_addition(self):
        changeset = (ROOT / ".changeset/PR-DRAFT-fabric-plan-skill.md").read_text(
            encoding="utf-8"
        )
        self.assertTrue(changeset.startswith("audience: public\n"))
        self.assertIn("### Added\n", changeset)
        self.assertIn("**`fabric-plan-skill`**", changeset)
        self.assertNotRegex(changeset, re.compile(r"Vally|eval|grader|tests?|CI", re.I))

    def test_skill_has_guidance_and_examples_sections(self):
        skill = (ROOT / "SKILL.md").read_text(encoding="utf-8")
        for heading in ("## Must/Prefer/Avoid", "### MUST DO", "### PREFER", "### AVOID", "## Examples"):
            self.assertIn(heading, skill)
        self.assertIn("x-ms-fabric-skill: fabric-plan-skill", skill)
        self.assertIn("public Fabric APIs", skill)
        self.assertIn("explicit write authorization", skill)
        self.assertIn("plan-cli", skill)
        self.assertIn("python scripts/plan.py build", skill)

    def test_fulleval_tags_cover_suite_and_every_stimulus(self):
        spec = (ROOT / "tests/evals/fabric-plan-skill-fulleval/eval.yaml").read_text(
            encoding="utf-8"
        )
        self.assertEqual(
            spec.count("\ntags:\n"),
            1,
            "the suite must have exactly one top-level tags mapping",
        )
        self.assertIn(
            "type: capability\n"
            "tags:\n"
            "  type: fulleval\n"
            "  plan: fabric-plan-skill\n"
            "scoring:",
            spec,
        )
        stimuli = re.split(r"(?m)^  - name: ", spec)[1:]
        self.assertEqual(len(stimuli), 5)
        for stimulus in stimuli:
            name = stimulus.splitlines()[0]
            with self.subTest(stimulus=name):
                self.assertEqual(stimulus.count("\n    tags:\n"), 1)
                self.assertIn(
                    "    tags:\n"
                    "      type: fulleval\n"
                    "      plan: fabric-plan-skill\n"
                    "    prompt: |",
                    stimulus,
                )
                self.assertNotIn("      tier:", stimulus)
                self.assertNotIn("      skill:", stimulus)


if __name__ == "__main__":
    unittest.main()
